<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api} from '@/api';import {useAuthStore} from '@/stores/auth';import {ElMessage} from 'element-plus';import {Plus,View,ChatLineRound,Star,TrendCharts} from '@element-plus/icons-vue';
const auth=useAuthStore(),posts=ref<any[]>([]),category=ref('全部'),dialog=ref(false),form=ref({category:'Web安全',title:'',content:''});const cats=['全部','Web安全','二进制安全','移动安全','云安全','AI安全','CTF'];const shown=computed(()=>category.value==='全部'?posts.value:posts.value.filter(p=>p.category===category.value));async function load(){try{posts.value=await api.get('/forum/posts')}catch{posts.value=[]}}onMounted(load);async function publish(){if(!auth.loggedIn){ElMessage.warning('请先登录');return}try{await api.post('/forum/posts',form.value);ElMessage.success('文章已发布');dialog.value=false;form.value={category:'Web安全',title:'',content:''};load()}catch(e:any){ElMessage.error(e.message)}}
</script>
<template><div class="page"><div class="page-head"><div><span class="eyebrow">Security knowledge network</span><h1>安全研究社区</h1><p>分享技术洞见、漏洞复盘与负责任披露实践。</p></div><el-button type="primary" :icon="Plus" @click="dialog=true">发布内容</el-button></div><div class="community-grid"><aside><div class="section-title">内容分类</div><nav class="categories"><button v-for="c in cats" :key="c" :class="{active:category===c}" @click="category=c"><span>{{c}}</span><em>{{c==='全部'?posts.length:posts.filter(p=>p.category===c).length}}</em></button></nav><div class="panel hot"><div class="panel-title"><h3><TrendCharts/>研究热榜</h3></div><ol><li v-for="(p,i) in posts.slice(0,5)" :key="p.id"><em>{{i+1}}</em><span>{{p.title}}</span></li></ol></div></aside><section><div class="feed-head"><span>{{category}} · 最新发布</span><small>{{shown.length}} TOPICS</small></div><article v-for="p in shown" :key="p.id" class="post"><div class="author-mark">{{p.author.slice(0,1)}}</div><div class="post-main"><div class="post-meta"><span class="tag">{{p.category}}</span><span>{{p.author}}</span><i>·</i><time>{{new Date(p.createdAt).toLocaleDateString()}}</time></div><h2>{{p.title}}</h2><p>{{p.content}}</p><div class="post-stats"><span><View/>{{p.views}}</span><span><ChatLineRound/>{{p.comments}}</span><span><Star/>{{p.likes}}</span></div></div></article><div v-if="!shown.length" class="empty panel">该分类暂时没有内容</div></section></div><el-dialog v-model="dialog" title="发布安全内容" width="min(650px,92vw)"><el-form label-position="top"><el-form-item label="分类"><el-select v-model="form.category"><el-option v-for="c in cats.slice(1)" :key="c" :label="c" :value="c"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="form.title" maxlength="200"/></el-form-item><el-form-item label="正文"><el-input v-model="form.content" type="textarea" :rows="8" maxlength="20000"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="publish">发布</el-button></template></el-dialog></div></template>
<style scoped>.community-grid{display:grid;grid-template-columns:250px 1fr;gap:18px}.categories{margin:10px 0 25px;border-top:1px solid #1d2c3d}.categories button{width:100%;border:0;border-bottom:1px solid #182839;background:transparent;color:#7890a5;display:flex;justify-content:space-between;padding:12px 10px;cursor:pointer;text-align:left}.categories button.active{color:#5cd9f5;background:#0d1b28;border-left:2px solid #39d5ff}.categories em{font:9px monospace}.hot h3{display:flex;gap:7px;align-items:center}.hot svg{width:15px;color:#ffbf5b}.hot ol{list-style:none;padding:5px 14px 12px;margin:0}.hot li{display:flex;gap:9px;padding:10px 0;border-bottom:1px solid #192939}.hot li em{font:10px monospace;color:#ffbf5b}.hot li span{font-size:10px;color:#879aaf;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.feed-head{display:flex;justify-content:space-between;padding:0 5px 12px;border-bottom:1px solid #294055;font-size:11px;color:#88a0b7}.feed-head small{font:9px monospace;color:#597086}.post{display:flex;gap:14px;padding:20px 8px;border-bottom:1px solid #1b2c3d}.author-mark{width:38px;height:38px;flex:0 0 38px;border:1px solid #28667e;background:#102a3a;color:#66d7f0;display:grid;place-items:center}.post-main{flex:1;min-width:0}.post-meta{display:flex;align-items:center;gap:8px;font-size:9px;color:#677c91}.post h2{font-size:16px;margin:11px 0 7px}.post p{font-size:11px;line-height:1.7;color:#788da2;margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.post-stats{display:flex;gap:18px;margin-top:13px;color:#63798e}.post-stats span{font:9px monospace;display:flex;gap:5px;align-items:center}.post-stats svg{width:13px}@media(max-width:700px){.community-grid{grid-template-columns:1fr}.community-grid>aside{display:none}}</style>
